import{_ as d,o as e,c as o,a5 as r}from"./chunks/framework.UjrY2eRK.js";const I=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"reference/configuration.md","filePath":"reference/configuration.md","lastUpdated":1788123021000}'),c={name:"reference/configuration.md"};function i(a,t,n,_,s,T){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="configuration-reference" tabindex="-1">Configuration reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration reference&quot;">​</a></h1><p>The table is rendered from the typed configuration reference used by repository contract tests. Secrets have no documented value. For Bun, a credential&#39;s <code>_FILE</code> setting is mutually exclusive with its direct setting.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Runtime</th><th>Required</th><th>Secret</th><th>Default</th><th>Constraint</th><th>Description</th></tr></thead><tbody><tr><td><code>TRINITY_PUSH_GATEWAY_ANDROID_APP_ID</code></td><td>cloudflare, bun</td><td>Yes</td><td>No</td><td>—</td><td>Must differ from the iOS application ID.</td><td>Android application ID accepted by the gateway.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_IOS_APP_ID</code></td><td>cloudflare, bun</td><td>Yes</td><td>No</td><td>—</td><td>Must differ from the Android application ID.</td><td>iOS application ID accepted by the gateway.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_FCM_CLIENT_EMAIL</code></td><td>cloudflare, bun</td><td>Yes</td><td>Secret</td><td>—</td><td>—</td><td>Client email from the dedicated Firebase service account.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_FCM_PRIVATE_KEY</code></td><td>cloudflare, bun</td><td>Yes</td><td>Secret</td><td>—</td><td>—</td><td>Complete PEM private key for the Firebase service account.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_FCM_PROJECT_ID</code></td><td>cloudflare, bun</td><td>Yes</td><td>Secret</td><td>—</td><td>—</td><td>Firebase project ID that owns both mobile applications.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_FINGERPRINT_KEY</code></td><td>cloudflare, bun</td><td>Yes</td><td>Secret</td><td>—</td><td>At least 32 UTF-8 bytes; do not reuse a Firebase secret.</td><td>Independent key used to fingerprint delivery attempts.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_MAX_BODY_BYTES</code></td><td>cloudflare, bun</td><td>No</td><td>No</td><td><code>65536</code></td><td>Positive integer.</td><td>Maximum accepted Matrix notification request size.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_MAX_DAILY_ATTEMPTS</code></td><td>cloudflare, bun</td><td>No</td><td>No</td><td><code>20000</code></td><td>Positive integer.</td><td>Maximum persisted FCM delivery attempts per UTC day.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_MAX_DEVICES</code></td><td>cloudflare, bun</td><td>No</td><td>No</td><td><code>49</code></td><td>Positive integer no greater than 49.</td><td>Maximum devices accepted in one Matrix notification.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_PENDING_LEASE_SECONDS</code></td><td>cloudflare, bun</td><td>No</td><td>No</td><td><code>120</code></td><td>Positive integer shorter than terminal retention.</td><td>Lease duration for an in-progress delivery.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_REQUEST_DEADLINE_SECONDS</code></td><td>cloudflare, bun</td><td>No</td><td>No</td><td><code>30</code></td><td>Positive integer greater than the upstream timeout.</td><td>Overall deadline for one gateway request.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_TERMINAL_RETENTION_SECONDS</code></td><td>cloudflare, bun</td><td>No</td><td>No</td><td><code>86400</code></td><td>Positive integer longer than the pending lease.</td><td>Retention time for completed delivery fingerprints.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_UPSTREAM_TIMEOUT_SECONDS</code></td><td>cloudflare, bun</td><td>No</td><td>No</td><td><code>10</code></td><td>Positive integer shorter than the request deadline.</td><td>Timeout for Google OAuth and FCM requests.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_FCM_CLIENT_EMAIL_FILE</code></td><td>bun</td><td>No</td><td>Secret</td><td>—</td><td>Mutually exclusive with the corresponding direct value.</td><td>FCM client-email secret file.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_FCM_PRIVATE_KEY_FILE</code></td><td>bun</td><td>No</td><td>Secret</td><td>—</td><td>Mutually exclusive with the corresponding direct value.</td><td>FCM private-key secret file.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_FCM_PROJECT_ID_FILE</code></td><td>bun</td><td>No</td><td>Secret</td><td>—</td><td>Mutually exclusive with the corresponding direct value.</td><td>FCM project-ID secret file.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_FINGERPRINT_KEY_FILE</code></td><td>bun</td><td>No</td><td>Secret</td><td>—</td><td>Mutually exclusive with the corresponding direct value.</td><td>Fingerprint-key secret file.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_HOST</code></td><td>bun</td><td>No</td><td>No</td><td><code>0.0.0.0</code></td><td>—</td><td>Address used by the Bun HTTP listener.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_PORT</code></td><td>bun</td><td>No</td><td>No</td><td><code>3000</code></td><td>Integer from 1 through 65535.</td><td>Port used by the Bun HTTP listener.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_DATABASE_PATH</code></td><td>bun</td><td>No</td><td>No</td><td><code>/data/gateway.sqlite</code></td><td>—</td><td>Path to the persistent SQLite database.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_MIGRATIONS_PATH</code></td><td>bun</td><td>No</td><td>No</td><td><code>/app/migrations</code></td><td>—</td><td>Path containing forward-only SQL migrations.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_SOURCE_RATE_LIMIT</code></td><td>bun</td><td>No</td><td>No</td><td><code>300</code></td><td>Positive integer.</td><td>Process-local request allowance per source period.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_SOURCE_RATE_PERIOD_SECONDS</code></td><td>bun</td><td>No</td><td>No</td><td><code>10</code></td><td>Positive integer.</td><td>Process-local source-rate window.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_MAX_SOURCE_KEYS</code></td><td>bun</td><td>No</td><td>No</td><td><code>10000</code></td><td>Positive integer.</td><td>Maximum source keys retained by the process-local limiter.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_CLEANUP_INTERVAL_SECONDS</code></td><td>bun</td><td>No</td><td>No</td><td><code>86400</code></td><td>Positive integer.</td><td>Interval between terminal-record cleanup passes.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_CLIENT_IP_HEADER</code></td><td>bun</td><td>No</td><td>No</td><td><code>x-forwarded-for</code></td><td>x-forwarded-for or cf-connecting-ip.</td><td>Forwarded client-address header trusted from configured proxies.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_TRUSTED_PROXY_CIDRS</code></td><td>bun</td><td>No</td><td>No</td><td>—</td><td>—</td><td>Comma-separated networks allowed to supply the client header.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_ENABLED</code></td><td>bun</td><td>No</td><td>No</td><td><code>false</code></td><td>Exact true or false; every other administration value is ignored while false.</td><td>Opt in to the isolated Bun administration surface.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_PUBLIC_ORIGIN</code></td><td>bun</td><td>No</td><td>No</td><td>—</td><td>Required when enabled; HTTPS without a path, query, or fragment, except loopback HTTP for development.</td><td>Exact same origin used by the Push Gateway UI and operator API.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_DATABASE_PATH</code></td><td>bun</td><td>No</td><td>No</td><td><code>/data/admin.sqlite</code></td><td>Absolute path distinct from the gateway database.</td><td>Path to the isolated administration SQLite database.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_ASSETS_PATH</code></td><td>bun</td><td>No</td><td>No</td><td><code>/app/admin</code></td><td>Absolute Bun-local path; excluded from the operator API.</td><td>Internal directory containing production browser assets.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_MIGRATIONS_PATH</code></td><td>bun</td><td>No</td><td>No</td><td><code>/app/admin-migrations</code></td><td>Absolute Bun-local path; excluded from the operator API.</td><td>Internal directory containing administration database migrations.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_BACKUP_DIRECTORY</code></td><td>bun</td><td>No</td><td>No</td><td><code>/data/backups</code></td><td>Absolute path on the persistent local volume.</td><td>Directory for verified gateway-database backups.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_BACKUP_LIMIT_COUNT</code></td><td>bun</td><td>No</td><td>No</td><td><code>24</code></td><td>Positive integer no greater than 1000.</td><td>Maximum verified backups retained in the backup directory.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_BACKUP_LIMIT_BYTES</code></td><td>bun</td><td>No</td><td>No</td><td><code>1073741824</code></td><td>Positive safe integer.</td><td>Maximum aggregate bytes allowed for verified backups.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_OIDC_ISSUER</code></td><td>bun</td><td>No</td><td>No</td><td>—</td><td>Required when enabled; HTTPS, except loopback HTTP for development.</td><td>Exact issuer URL discovered for Operator authentication.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_OIDC_CLIENT_ID</code></td><td>bun</td><td>No</td><td>No</td><td>—</td><td>Required when enabled.</td><td>Confidential OIDC client identifier.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_OIDC_CLIENT_SECRET</code></td><td>bun</td><td>No</td><td>Secret</td><td>—</td><td>Required directly or by file when enabled; mutually exclusive with its file alternative.</td><td>Confidential OIDC client secret.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_OIDC_CLIENT_SECRET_FILE</code></td><td>bun</td><td>No</td><td>Secret</td><td>—</td><td>Required directly or by file when enabled; mutually exclusive with its direct alternative.</td><td>Confidential OIDC client-secret file.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_OIDC_SCOPES</code></td><td>bun</td><td>No</td><td>No</td><td><code>openid profile email groups</code></td><td>Unique scopes including openid; offline_access is forbidden.</td><td>Whitespace-separated OIDC scopes requested at login.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_OIDC_GROUP_CLAIM</code></td><td>bun</td><td>No</td><td>No</td><td><code>groups</code></td><td>—</td><td>Top-level ID-token claim containing exact group values.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_OIDC_REQUIRED_GROUP</code></td><td>bun</td><td>No</td><td>No</td><td>—</td><td>Required when enabled.</td><td>Exact case-sensitive group required for Operator access.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_OIDC_TOKEN_ENDPOINT_AUTH_METHOD</code></td><td>bun</td><td>No</td><td>No</td><td><code>client_secret_basic</code></td><td>client_secret_basic or client_secret_post.</td><td>Confidential-client token endpoint authentication method.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_SESSION_SECRET</code></td><td>bun</td><td>No</td><td>Secret</td><td>—</td><td>At least 32 UTF-8 bytes and required directly or by file when enabled; mutually exclusive with its file alternative.</td><td>Independent secret used to protect Operator Sessions.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_ADMIN_SESSION_SECRET_FILE</code></td><td>bun</td><td>No</td><td>Secret</td><td>—</td><td>Required directly or by file when enabled; mutually exclusive with its direct alternative.</td><td>Operator Session secret file.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_HOST_PORT</code></td><td>compose</td><td>No</td><td>No</td><td><code>3000</code></td><td>—</td><td>Loopback host port published by Docker Compose.</td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_VERSION</code></td><td>compose</td><td>No</td><td>No</td><td><code>latest</code></td><td>Pin an immutable vX.Y.Z tag or digest in production.</td><td>Container tag or digest selected by Docker Compose.</td></tr></tbody></table><p>Cloudflare-specific D1 and rate-limit bindings are configured in <code>apps/push-gateway/wrangler.jsonc</code>. Docker Compose additionally consumes its host-side version and port settings without passing them to the Bun process.</p>',4)])])}const u=d(c,[["render",i]]);export{I as __pageData,u as default};
